def transform(g):
    g=[r[:] for r in g]; R=len(g); C=len(g[0])
    for cells in regions(g):
        col=[(a,b) for a,b in cells if g[a][b]!=0]
        i0=min(a for a,b in col); i1=max(a for a,b in col)
        j0=min(b for a,b in col); j1=max(b for a,b in col)
        ph,pw=i1-i0+1, j1-j0+1
        seed=[[g[i0+a][j0+b] if g[i0+a][j0+b]!=0 else 0 for b in range(pw)] for a in range(ph)]
        r0=min(a for a,b in cells); r1=max(a for a,b in cells)
        c0=min(b for a,b in cells); c1=max(b for a,b in cells)
        for i in range(r0,r1+1):
            for j in range(c0,c1+1):
                g[i][j]=seed[(i-i0)%ph][(j-j0)%pw]
    return g

